);\n\n  vector<long long> ans(m, 0);\n  vector<int> bit(ny+2, 0);\n  auto bit_add = [&](int idx0, int delta){\n    int idx = idx0 + 1;\n    while(idx <= ny){ bit[idx] += delta; idx += idx & -idx; }\n  };\n  auto bit_sum = [&](int idx0){\n    int idx = idx0 + 1; long long s = 0;\n    while(idx > 0){ s += bit[idx]; idx -= idx & -idx; }\n    return s;\n  };\n  auto range_sum = [&](int l0, int r0){\n    if(l0 > r0) return 0LL;\n    return bit_sum(r0) - (l0 ? bit_sum(l0 - 1) : 0LL);\n  };\n\n  int idxPt = 0;\n  for(const auto &e : ev){\n    while(idxPt < n && points[idxPt].first <= e.x){\n      bit_add(points[idxPt].second, 1);\n      ++idxPt;\n    }\n    long long cur = range_sum(e.l, e.r);\n    ans[e.id] += (long long)e.sign * cur;\n  }\n\n  for(int i = 0; i < m; ++i){\n    cout << ans[i] << \"\\n\";\n  }\n  return 0;\n}\nCPP\n",
