        N = n;
        g.assign(2*N, {});
        gr.assign(2*N, {});
    }
    void add_imp(int a, int b){
        g[a].push_back(b);
        gr[b].push_back(a);
    }
    // add clause (A or B), where A and B are literals encoded as indices in [0, 2*N)
    void add_or(int A, int B){
        int nA = A ^ 1;
        int nB = B ^ 1;
        add_imp(nA, B);
        add_imp(nB, A);
    }
    // unit clause (A)
    void add_unit(int A){
        add_or(A, A);
    }
    // solve, returns assignment of size N if SAT, else empty vector
    vector<int> solve(){
        int M = 2*N;
        comp.assign(M, -1);
        vector<char> used(M, false);
        order.clear();
        function<void(int)> dfs1 = [&](int v){
            used[v] = true;
            for(int to: g[v]) if(!used[to]) dfs1(to);
            order.push_back(v);
        };
        for(int i=0;i<M;++i) if(!used[i]) dfs1(i);
        int j = 0;
        function<void(int)> dfs2 = [&](int v){
            comp[v] = j;
            for(int to: gr[v]) if(comp[to] == -1) dfs2(to);
        };
        for(int i=M-1;i>=0;--i){
            int v = order[i];
            if(comp[v] == -1){
                dfs2(v);
                ++j;
            }
        }
        val.assign(N, 0);
        for(int i=0;i<N;++i){
            if(comp[2*i] == comp[2*i+1]) return {}; // unsat
            val[i] = comp[2*i] > comp[2*i+1];
        }
        return val;
    }
};

